import pty, os, sys, select, time

def run_in_pty(args, stdin_tty=True, stdout_tty=True, stderr_tty=True, input_data=b''):
    if stdin_tty:
        master_in, slave_in = pty.openpty()
    else:
        r_in, w_in = os.pipe()
    if stdout_tty:
        master_out, slave_out = pty.openpty()
    else:
        r_out, w_out = os.pipe()
    if stderr_tty:
        master_err, slave_err = pty.openpty()
    else:
        r_err, w_err = os.pipe()

    pid = os.fork()
    if pid == 0:
        if stdin_tty:
            os.dup2(slave_in, 0); os.close(master_in); os.close(slave_in)
        else:
            os.dup2(r_in, 0); os.close(r_in); os.close(w_in)
        if stdout_tty:
            os.dup2(slave_out, 1); os.close(master_out); os.close(slave_out)
        else:
            os.dup2(w_out, 1); os.close(r_out); os.close(w_out)
        if stderr_tty:
            os.dup2(slave_err, 2); os.close(master_err); os.close(slave_err)
        else:
            os.dup2(w_err, 2); os.close(r_err); os.close(w_err)
        os.execv('/workspace/executable', ['./executable'] + args)
    if stdin_tty:
        os.close(slave_in)
        if input_data: os.write(master_in, input_data)
    else:
        os.close(r_in)
        if input_data: os.write(w_in, input_data)
        os.close(w_in)
    if stdout_tty: os.close(slave_out)
    else: os.close(w_out)
    if stderr_tty: os.close(slave_err)
    else: os.close(w_err)

    out_data = b""; err_data = b""
    out_fd = master_out if stdout_tty else r_out
    err_fd = master_err if stderr_tty else r_err
    fds = [out_fd, err_fd]
    time.sleep(0.2)
    while fds:
        r, _, _ = select.select(fds, [], [], 1.0)
        if not r: break
        for f in r:
            try:
                d = os.read(f, 4096)
                if not d:
