func main() {
	inputs := []string{"", ":", ":/", ":/path", ":1", ":8080", ":#frag", ":?q", "::", ":::", 
		"://", "://x", "://:8080", "user@:8080", "x://", "//path", "/path", "foo", 
		"foo:8080", "foo:/path", "http:foo", "http:foo/", "h"}
	for _, input := range inputs {
		var prepended string
		if strings.HasPrefix(input, "http") {
			prepended = input
		} else if strings.HasPrefix(input, "//") {
			prepended = "http:" + input
		} else {
			prepended = "http://" + input
		}
		u, err := url.Parse(prepended)
		if err != nil {
			fmt.Printf("Input=%q Prepended=%q ERR=%v\n", input, prepended, err)
			continue
		}
		// Transform: if Host starts with ":"
		if strings.HasPrefix(u.Host, ":") {
			if u.Host == ":" {
				u.Host = "localhost"
			} else {
				u.Host = "localhost" + u.Host
			}
		}
		// For curl: remove scheme if we added it
		var curlURL string
		if strings.HasPrefix(input, "http") {
			curlURL = u.String()
		} else {
			u.Scheme = ""
			curlURL = u.String()
			curlURL = strings.TrimPrefix(curlURL, "//")
		}
		fmt.Printf("Input=%-20q Prepended=%-22q Parsed={Scheme:%q Host:%q Path:%q Q:%q F:%q} Curl=%q\n", 
			input, prepended, u.Scheme, u.Host, u.Path, u.RawQuery, u.Fragment, curlURL)
	}
}
