package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// PrettyJSON reads from r and writes a colourised / indented version to w when
// the payload starts with "{" or "[".  Otherwise the input is copied verbatim.
func PrettyJSON(r io.Reader, w io.Writer) error {
	br := bufio.NewReader(r)
	first, err := readFirstNonWhite(br)
	if err == io.EOF {
		return nil
	}
	if err != nil {
		return err
	}
	if first != '{' && first != '[' {
		if _, err := fmt.Fprintf(w, "%c", first); err != nil {
			return err
		}
		_, err := io.Copy(w, br)
		return err
	}
	if err := br.UnreadByte(); err != nil {
		return err
	}
	return prettyPrintJSON(br, w)
}

// readFirstNonWhite skips leading whitespace and returns the first real byte.
func readFirstNonWhite(br *bufio.Reader) (byte, error) {
	for {
		b, err := br.ReadByte()
		if err != nil {
			return 0, err
		}
		if b == ' ' || b == '\n' || b == '\r' || b == '\t' {
			continue
		}
		return b, nil
	}
}

// context tracks whether we are currently emitting an object's key, its value
// or an element of an array.  It drives the colour selection.
type ctxKind int

const (
	ctxTop ctxKind = iota
	ctxObjectKey
	ctxObjectValue
	ctxArray
)

type jsonFormatter struct {
	w       io.Writer
	dec     *json.Decoder
	indent  int
	stack   []ctxKind
	err     error
}

func prettyPrintJSON(r io.Reader, w io.Writer) error {
	f := &jsonFormatter{w: w, dec: json.NewDecoder(r)}
	f.dec.UseNumber()
	f.stack = []ctxKind{ctxTop}
	for {
		tok, err := f.dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
		f.emit(tok)
		if f.err != nil {
			return f.err
		}
	}
	fmt.Fprint(w, cReset)
	return nil
}

func (f *jsonFormatter) write(s string) {
	if f.err != nil {
		return
	}
	_, f.err = io.WriteString(f.w, s)
}

func (f *jsonFormatter) currentCtx() ctxKind {
	return f.stack[len(f.stack)-1]
}

// onValueBoundary is called each time a scalar/value is about to be emitted.
