package main

import (
	"fmt"
	"net/url"
	"os"
	"strings"
)

// transformURL produces the URL to display to the user and the URL to pass to
// curl.  The curl URL is obtained by running the "prepended" form through
// net/url so that cases like ":8080" can become "localhost:8080".
func transformURL(raw string) (display, forCurl string) {
	display = prependHTTP(raw)
	u, err := url.Parse(display)
	if err != nil {
		// Mimic the Go library's "parse %q: %v" wrapping which the real
		// tool prints to stdout without a trailing newline.
		fmt.Fprint(os.Stdout, err.Error())
		return display, display
	}
	// If the host is missing or only a port, substitute localhost.
	if u.Host == ":" {
		u.Host = "localhost"
	} else if strings.HasPrefix(u.Host, ":") {
		u.Host = "localhost" + u.Host
	}

	rebuilt := u.String()
	if strings.HasPrefix(raw, "http") {
		// The caller supplied a scheme; keep the URL intact.
		forCurl = rebuilt
	} else {
		// We added the "http://" prefix; remove it for the curl arg.
		forCurl = strings.TrimPrefix(rebuilt, "http://")
	}
	return display, forCurl
}

// prependHTTP adds http:// when the argument does not start with a known
// scheme.  A leading "//" is treated as a scheme-relative URL and gets only
// "http:" prepended.
func prependHTTP(s string) string {
	if strings.HasPrefix(s, "http") {
		return s
	}
	if strings.HasPrefix(s, "//") {
		return "http:" + s
	}
	return "http://" + s
}
