package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
	"syscall"
)

func main() {
	parsed := ParseArgs(os.Args[1:])

	stdinTTY := isTerminal(os.Stdin.Fd())
	stdoutTTY := isTerminal(os.Stdout.Fd())
	stderrTTY := isTerminal(os.Stderr.Fd())

	colorizeHeaders := parsed.Pretty || stderrTTY
	addVerbose := (parsed.Pretty || stderrTTY) && !parsed.HasVerbose
	prettifyBody := parsed.Pretty || stdoutTTY

	var displayURL, curlURL string
	if parsed.HasURL {
		displayURL, curlURL = transformURL(parsed.URL)
	}

	items := collectItems(parsed.Items)

	// Build the curl argument list.
	curlArgs := []string{}
	curlArgs = append(curlArgs, parsed.CurlArgs...)

	if parsed.Method != "" {
		if parsed.Method == "HEAD" {
			curlArgs = append(curlArgs, "-I")
		} else {
			curlArgs = append(curlArgs, "-X", parsed.Method)
		}
	}

	// Item-derived headers.
	for _, h := range items.Headers {
		curlArgs = append(curlArgs, "-H", h[0]+":"+h[1])
	}

	// Data: either JSON body or -F form fields.
	hasJSONData := (len(items.Data) > 0 || len(items.Raw) > 0) && !parsed.Form
	if parsed.Form {
		for _, k := range items.DataKeys {
			if v, ok := items.Data[k]; ok {
				curlArgs = append(curlArgs, "-F", k+"="+v)
			} else if v, ok := items.Raw[k]; ok {
				curlArgs = append(curlArgs, "-F", k+"="+string(v))
			}
		}
	} else if hasJSONData {
		curlArgs = append(curlArgs, "-d", items.buildJSON())
	}

	for _, u := range items.Unknown {
		curlArgs = append(curlArgs, u)
	}

	if parsed.HasURL {
		displayURL = appendQueryString(displayURL, items.Query)
		finalURL := appendQueryString(curlURL, items.Query)
		curlArgs = append(curlArgs, finalURL)
	}

	// -s -S always.
	curlArgs = append(curlArgs, "-s", "-S")

	if addVerbose {
		curlArgs = append(curlArgs, "-v")
	}

	// Determine whether we should feed stdin as the request body.
	userHasExplicitData := userProvidesData(parsed.CurlArgs)
	needStdinData := !stdinTTY && !userHasExplicitData && !hasJSONData
	if needStdinData {
		curlArgs = append(curlArgs, "-d@-")
	}

	// Default Content-Type header unless we're in form mode (curl handles
	// that) or the user supplied their own Content-Type, and we're actually
	// sending some data.
	sendingData := hasJSONData || needStdinData
	if !parsed.Form && sendingData && !userHeaderPresent(items.Headers, "Content-Type") {
		curlArgs = append(curlArgs, "-H", "Content-Type: application/json")
	}
	if !userHeaderPresent(items.Headers, "Accept") {
		curlArgs = append(curlArgs, "-H", "Accept: application/json, */*")
	}

	if parsed.HasURL {
		fmt.Fprintln(os.Stderr, displayURL)
	}

	if parsed.PrintCurl {
		fmt.Println(formatCurlCommand(curlArgs))
		return
	}

	cmd := exec.Command("curl", curlArgs...)
	cmd.Stdin = os.Stdin

	if prettifyBody {
		stdout, err := cmd.StdoutPipe()
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		go func() {
			_ = PrettyJSON(stdout, os.Stdout)
		}()
	} else {
		cmd.Stdout = os.Stdout
	}

	if addVerbose || parsed.HasVerbose {
		stderr, err := cmd.StderrPipe()
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		go func() {
			_ = processHeaders(stderr, os.Stderr, parsed.HasVerbose, colorizeHeaders)
		}()
	} else {
		cmd.Stderr = os.Stderr
	}

	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			if ws, ok := exitErr.Sys().(syscall.WaitStatus); ok {
				os.Exit(ws.ExitStatus())
			}
			os.Exit(1)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func userHeaderPresent(headers [][2]string, name string) bool {
	for _, h := range headers {
		if strings.EqualFold(h[0], name) {
			return true
		}
	}
	return false
}

func userProvidesData(args []string) bool {
	for _, a := range args {
		if a == "-d" || strings.HasPrefix(a, "--data") {
			return true
		}
	}
	return false
}

func formatCurlCommand(args []string) string {
	var b strings.Builder
	b.WriteString("curl")
	for _, a := range args {
		b.WriteByte(' ')
		b.WriteString(quoteForShell(a))
	}
	return b.String()
}

func quoteForShell(s string) string {
	if !strings.ContainsAny(s, " \t") {
		return s
	}
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' || c == '\\' {
			b.WriteByte('\\')
		}
		b.WriteByte(c)
	}
	b.WriteByte('"')
	return b.String()
}
