import os, select, pty, time, http.server, json, threading

class Handler(http.server.BaseHTTPRequestHandler):
    def _respond(self):
        typ = self.path.strip('/').split('/')[0] if self.path != '/' else 'json'
        if typ == 'json':
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(b'{"key":"value","num":42,"arr":[1,2,3],"obj":{"nested":true}}')
        elif typ == 'text':
            self.send_response(200)
            self.send_header('Content-Type', 'text/plain')
            self.end_headers()
            self.wfile.write(b'hello world')
        elif typ == 'echo':
            body = b''
            try:
                body = self.rfile.read(int(self.headers.get('Content-Length', 0)))
            except: pass
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({'method':self.command,'path':self.path,'body':body.decode('utf-8', errors='replace'),'ct':self.headers.get('Content-Type','')}).encode())
    do_GET = _respond
    do_POST = _respond
    do_HEAD = _respond
    do_PUT = _respond
    do_DELETE = _respond
    do_PATCH = _respond
    def log_message(self, *a): pass

srv = http.server.HTTPServer(('127.0.0.1', 8900), Handler)
tt = threading.Thread(target=srv.serve_forever); tt.daemon=True; tt.start()
time.sleep(0.3)

def run(path, args, stdin_tty=False, stdout_tty=False, stderr_tty=False, input_data=b''):
    if stdin_tty: master_in, slave_in = pty.openpty()
    else: r_in, w_in = os.pipe()
    if stdout_tty: master_out, slave_out = pty.openpty()
    else: r_out, w_out = os.pipe()
    if stderr_tty: master_err, slave_err = pty.openpty()
    else: r_err, w_err = os.pipe()
    pid = os.fork()
    if pid == 0:
        if stdin_tty: os.dup2(slave_in,0); os.close(master_in); os.close(slave_in)
        else: os.dup2(r_in,0); os.close(r_in); os.close(w_in)
        if stdout_tty: os.dup2(slave_out,1); os.close(master_out); os.close(slave_out)
        else: os.dup2(w_out,1); os.close(r_out); os.close(w_out)
        if stderr_tty: os.dup2(slave_err,2); os.close(master_err); os.close(slave_err)
        else: os.dup2(w_err,2); os.close(r_err); os.close(w_err)
        os.execv(path, [path]+args)
    if stdin_tty: os.close(slave_in)
    else: os.close(r_in)
    if input_data:
        if stdin_tty: os.write(master_in, input_data)
        else: os.write(w_in, input_data)
    if not stdin_tty: os.close(w_in)
    if stdout_tty: os.close(slave_out)
    else: os.close(w_out)
    if stderr_tty: os.close(slave_err)
    else: os.close(w_err)
    out_fd = master_out if stdout_tty else r_out
    err_fd = master_err if stderr_tty else r_err
    out=b''; err=b''
    fds=[out_fd, err_fd]
    time.sleep(0.2)
    while fds:
        r,_,_ = select.select(fds,[],[],1.5)
        if not r: break
        for f in r:
            try:
                d = os.read(f,4096)
                if not d: fds.remove(f); continue
                if f==out_fd: out+=d
                else: err+=d
            except OSError: fds.remove(f)
    os.waitpid(pid,0)
    return out, err

def compare(args, **kw):
    # Strip dates since those differ
    def strip(s): 
        import re
        s = re.sub(rb'Date:[^\r\n]*', b'Date: DATE', s)
        return s
    o1, e1 = run('/workspace/executable', args, **kw)
    o2, e2 = run('/tmp/curlie', args, **kw)
    return strip(o1)==strip(o2) and strip(e1)==strip(e2), o1, e1, o2, e2

