    (['GET', URL+'/json'], {}),
    (['GET', URL+'/json'], {'stdout_tty': True}),
    (['GET', URL+'/json'], {'stderr_tty': True}),
    (['GET', URL+'/json'], {'stdin_tty': True, 'stdout_tty': True, 'stderr_tty': True}),
    (['--pretty', 'GET', URL+'/json'], {}),
    (['GET', URL+'/text'], {}),
    (['GET', URL+'/text'], {'stdout_tty': True}),
    (['--pretty', 'GET', URL+'/text'], {}),
    (['POST', URL+'/echo', 'name=bob', 'age:=30'], {}),
    (['-v', 'GET', URL+'/json'], {}),
    (['-v', 'GET', URL+'/json'], {'stderr_tty': True}),
    (['--pretty', '-v', 'GET', URL+'/json'], {}),
]
diff = 0
for i, (args, kw) in enumerate(TESTS):
    ok, o1, e1, o2, e2 = compare(args, **kw)
