        diff += 1
        print(f"DIFF {i}: {args} {kw}")
        print(f"  orig OUT: {o1!r}")
        print(f"  mine OUT: {o2!r}")
        print(f"  orig ERR: {e1!r}")
        print(f"  mine ERR: {e2!r}")
        print()
print(f"Total DIFFs: {diff}/{len(TESTS)}")
