package main

import (
	"bufio"
	"fmt"
	"io"
	"strings"
)

// ANSI color codes used for header / status-line output.
const (
	cReset   = "\x1b[0m"
	cWhite   = "\x1b[37m"
	cBlue    = "\x1b[34m"
	cCyan    = "\x1b[36m"
	cYellow  = "\x1b[33m"
	cMagenta = "\x1b[35m"
	cGray    = "\x1b[90m"
)

// processHeaders reads curl's verbose output line-by-line and writes a filtered
// (and optionally colorised) version of it to w.
//
// When verboseKept is true all of curl's verbose lines are emitted; otherwise
// only response headers are kept.  colorize enables ANSI colours on kept
// lines.
func processHeaders(r io.Reader, w io.Writer, verboseKept, colorize bool) error {
	br := bufio.NewReader(r)
	for {
		line, err := br.ReadString('\n')
		if len(line) > 0 {
			writeProcessedLine(w, line, verboseKept, colorize)
		}
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
	}
}

func writeProcessedLine(w io.Writer, line string, verboseKept, colorize bool) {
	body := line
	suffix := ""
	if strings.HasSuffix(body, "\n") {
		suffix = "\n"
		body = body[:len(body)-1]
	}
	// Strip a possible CR so we can classify the line.
	trimmed := strings.TrimSuffix(body, "\r")

	if strings.HasPrefix(body, "* ") || strings.HasPrefix(body, "*  ") {
		// Debug/trace line (always starts with "*").
		if !verboseKept {
			return
		}
		if colorize {
			fmt.Fprint(w, cGray, body, cReset, suffix)
		} else {
			fmt.Fprint(w, body, suffix)
		}
		return
	}

	// Curl data-transfer info lines: "{ [N bytes data]" or "} [N bytes data]".
	if strings.HasPrefix(body, "{ [") || strings.HasPrefix(body, "} [") {
		return
	}

	if strings.HasPrefix(body, "> ") {
		if !verboseKept {
			return
		}
		stripped := body[2:]
		writeHeaderLike(w, stripped, colorize, suffix)
		return
	}
	if body == ">" {
		// The blank line separating request headers from body in verbose.
		if !verboseKept {
			return
		}
		fmt.Fprint(w, suffix)
		return
	}
	if strings.HasPrefix(body, "< ") {
		stripped := body[2:]
		writeHeaderLike(w, stripped, colorize, suffix)
		return
	}
	if body == "<" || trimmed == "<" {
		// Empty response header separator line.
		// Remaining bytes are just "\r" or nothing plus the suffix.
		rest := strings.TrimPrefix(body, "<")
		fmt.Fprint(w, rest, suffix)
		return
	}

	// Default: keep line if verbose is requested.
	if verboseKept {
		fmt.Fprint(w, body, suffix)
	}
}

// writeHeaderLike colorizes (if requested) a single request or response header
// line produced by curl -v.  The line may contain a trailing CR from curl
// which we preserve.
func writeHeaderLike(w io.Writer, line string, colorize bool, suffix string) {
	if !colorize {
		fmt.Fprint(w, line, suffix)
		return
	}
	// Split the CR so we can append the reset right before it.
	hasCR := strings.HasSuffix(line, "\r")
	if hasCR {
		line = line[:len(line)-1]
	}
	if line == "" {
		if hasCR {
			fmt.Fprint(w, "\r")
		}
		fmt.Fprint(w, suffix)
		return
	}
	out := colorizeBody(line)
	if hasCR {
		out += "\r" + cReset
	} else {
		out += cReset
	}
	fmt.Fprint(w, out, suffix)
}

func colorizeBody(line string) string {
	if strings.HasPrefix(line, "HTTP/") {
		return colorizeStatusLine(line)
	}
	// Request line such as "GET /path HTTP/1.1".
	if idx := strings.Index(line, " "); idx > 0 {
		word := line[:idx]
		if isAllUpper(word) && idx+1 < len(line) {
			rest := line[idx+1:]
			if hp := strings.LastIndex(rest, " HTTP/"); hp >= 0 {
				path := rest[:hp]
				version := rest[hp+1:]
				return cBlue + word + cWhite + " " + path + " " + colorizeStatusLine(version)
			}
		}
	}
	if i := strings.Index(line, ":"); i >= 0 {
		name := line[:i+1]
		rest := line[i+1:]
		return cWhite + name + cCyan + rest
	}
	return line
}

func colorizeStatusLine(line string) string {
	slash := strings.Index(line, "/")
	if slash < 0 {
		return line
	}
	word := line[:slash]
	rest := line[slash+1:]
	firstSpace := strings.Index(rest, " ")
	if firstSpace < 0 {
		return cBlue + word + cWhite + "/" + cCyan + rest
	}
	version := rest[:firstSpace]
	afterVer := rest[firstSpace+1:]
	secondSpace := strings.Index(afterVer, " ")
	if secondSpace < 0 {
		return cBlue + word + cWhite + "/" + cCyan + version + " " + afterVer
	}
	statusCode := afterVer[:secondSpace]
	statusText := afterVer[secondSpace:]
	return cBlue + word + cWhite + "/" + cCyan + version + " " + statusCode + cYellow + statusText
}

func isAllUpper(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < 'A' || r > 'Z' {
			return false
		}
	}
	return true
}
