func userHeaderPresent(headers [][2]string, name string) bool {
	for _, h := range headers {
		if strings.EqualFold(h[0], name) {
			return true
		}
	}
	return false
}

func userProvidesData(args []string) bool {
	for _, a := range args {
		if a == "-d" || strings.HasPrefix(a, "--data") {
			return true
		}
	}
	return false
}

func hasHelpFlag(args []string) bool {
	for _, a := range args {
		if a == "-h" || a == "--help" {
			return true
		}
	}
	return false
}

func formatCurlCommand(args []string) string {
	var b strings.Builder
	b.WriteString("curl")
	for _, a := range args {
		b.WriteByte(' ')
		b.WriteString(quoteForShell(a))
	}
	return b.String()
}

func quoteForShell(s string) string {
	if !strings.ContainsAny(s, " \t") {
		return s
