// usageRewriter wraps an io.Writer and rewrites the first occurrence of the
// well-known curl "Usage:" line to match curlie's own usage banner.
type usageRewriter struct {
	w        io.Writer
	prefix   string
	buf      []byte
	done     bool
}

func newUsageRewriter(w io.Writer, progName string) *usageRewriter {
	return &usageRewriter{
		w:      w,
		prefix: fmt.Sprintf("Usage: %s [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]\n", progName),
	}
}

func (u *usageRewriter) Write(p []byte) (int, error) {
	n := len(p)
	if u.done {
		return u.w.Write(p)
	}
	u.buf = append(u.buf, p...)
	idx := bytes.IndexByte(u.buf, '\n')
	if idx < 0 {
		// Still reading the first line.  Flush early if it already diverges.
		if !isPrefixCompatible(u.buf, []byte(curlUsageLine)) {
			u.done = true
			if _, err := u.w.Write(u.buf); err != nil {
				return n, err
			}
			u.buf = nil
		}
		return n, nil
	}
	firstLine := u.buf[:idx]
	rest := u.buf[idx+1:]
	u.done = true
	u.buf = nil
	if bytes.Equal(firstLine, []byte(curlUsageLine)) {
		if _, err := u.w.Write([]byte(u.prefix)); err != nil {
			return n, err
		}
	} else {
		if _, err := u.w.Write(append(firstLine, '\n')); err != nil {
			return n, err
		}
	}
	if len(rest) > 0 {
		if _, err := u.w.Write(rest); err != nil {
			return n, err
		}
	}
	return n, nil
}

// Close flushes any pending buffered bytes.
func (u *usageRewriter) Close() {
	if u.done {
		return
	}
	u.done = true
	if len(u.buf) > 0 {
		_, _ = u.w.Write(u.buf)
		u.buf = nil
	}
}

// isPrefixCompatible returns true when the bytes in a form a legitimate prefix
// of b (both of arbitrary lengths).
func isPrefixCompatible(a, b []byte) bool {
	if len(a) > len(b) {
		return false
	}
	return bytes.Equal(a, b[:len(a)])
}
